prompt._raw_prompt:
"{
  "图像元数据": {
    "类型": "360度等距柱状全景图",
    "投影方式": "完整球形等距柱状投影",
    "宽高比": "2:1",
    "分辨率": "超高分辨率全景"
  },
  "场景构图": {
    "地点": "高山河谷地区（例如中国西南部或喜马拉雅山脉）",
    "相机位置": "360度全景无人机",
    "相机高度": "极高的高空航拍视角（上帝视角）",
    "视野范围": "水平360度，垂直180度，完全包围",
    "投影行为": "正确的等距柱状畸变，确保无缝球形拼接，天空在顶部，地面在底部",
    "天气状况": "晴朗，有动态积云",
    "景深": "无限景深，所有元素（前景道路、中景梯田、远景山脉）都锐利清晰"
  },
  "视觉元素": {
    "前景（地面半球底部）": {
      "主体视图": "一条维护良好的铺砌沥青道路，呈极度夸张、扭曲的“U”形环绕，并连接到中景的蜿蜒道路，展示了全景投影的典型畸变。道路两侧是干旱和半干旱的灌木丛和岩石地面。",
      "动态": "无车辆，无行人，保持纯净的自然景观"
    },
    "中景主体": {
      "地形": "一座雄伟、复杂的梯田山脉系统，完全覆盖了中景的大部分区域。梯田由人工修筑，呈现出惊人的同心圆、螺旋状和锯齿状几何图案，随着山体地形起伏，非常详细和庞大。梯田本身表现出绿色（作物）和棕色（土壤/干草）交织的自然调色板。",
      "村落": "一个密集的、历史悠久的村落（石砌建筑和传统屋顶）栖息在梯田山脉的脊线和山坡上，与梯田融为一体。另一个较小的定居点位于更远的山谷深处。右侧山坡上有几座红瓦屋顶的现代建筑。",
      "云雾": "低空积云和地形云（白而蓬松）从左侧山脉上方掠过，部分遮挡了最高的山峰，增加了深度和动感。"
    },
    "背景（天际线及以上）": {
      "景观": "一系列更遥远、更黑暗的常绿森林山脉环绕着山谷，与梯田山脉形成鲜明对比。远处的山脉向地平线延伸，展示出明显的层叠效果。",
      "天空": "深蓝色、纯净的天空，带有精致的卷云和蓬松的积云。太阳位于天空的右上角（或由于全景视角而看起来像在两个位置），投射出清晰的光线和阴影。"
    },
    "环境氛围": {
      "地面半球": "完全覆盖，从最底部扭曲的道路到中景的梯田，没有空白区域。",
      "整体氛围": "史诗般、宏大、偏远、宁静、农业文明与自然的和谐，具有极强的沉浸感。"
    }
  },
  "渲染风格": {
    "光照": "明亮的自然日光，具有明确的方向性（从右/上），产生强烈的阴影和高光，强调梯田的几何结构。左侧山脉有轻微的云阴影。",
    "调色": "自然、饱和、现实的色彩：深蓝色的天空，绿色、金棕色和岩石灰色的梯田和山体，深绿色的森林。",
    "质感质量": {
      "描述": "超高细节、摄影级写实，无噪点或压缩痕迹。",
      "痕迹": "无用户界面、无文本、无水印、无现代车辆或不协调的现代设施（除了少数红顶建筑）。",
      "拼接": "完美的360度无缝拼接，无任何可见接缝。"
    }
  },
  "约束条件": {
    "必须保留": [
      "纯360度全景透视",
      "无人机高空视角",
      "梯田为核心主体",
      "无任何界面元素",
      "高度写实摄影感",
      "前景道路的扭曲畸变"
    ],
    "必须避免": [
      "城市或现代大都市建筑",
      "人物",
      "电影感夸张灯光",
      "奇幻或游戏风格",
      "绘画或插画感",
      "非全景的普通照片布局"
    ]
  },
  "负面提示词": [
    "用户界面",
    "抬头显示",
    "文本覆盖",
    "水印",
    "签名",
    "边界线",
    "裁剪",
    "普通视角",
    "2D照片",
    "现代摩天大楼",
    "大量汽车",
    "行人",
    "奇幻艺术",
    "插图",
    "低分辨率",
    "全景接缝断裂",
    "伪造全景"
  ]
}
